pub fn find(name: []const u8) ?Preset {
    for (presets) |p| if (std.mem.eql(u8, p.name, name)) return p;
    return null;
}

pub fn findIn(name: []const u8, source: []const u8) ?Preset {
    for (presets) |p| {
        if (std.mem.eql(u8, p.name, name) and std.mem.eql(u8, p.source, source)) return p;
    }
    return null;
}

test "settings-theme-data: full reference preset roster" {
    const t = std.testing;
    try t.expectEqual(@as(usize, 268), presets.len);
    try t.expect(find("Catppuccin Mocha") != null);
    try t.expect(findIn("Google Dark", "google") != null);
    try t.expect(findIn("Google Dark", "nope") == null);
    try t.expect(find("Dracula") != null);
    const mocha = find("Catppuccin Mocha").?;
    try t.expectApproxEqAbs(@as(f32, 0.804), mocha.palette.primary[0], 1e-6);
}
